<?php $net = $sales - $credits - $bills - $expTotal; ?>
<div class="top"><div><h2 style="margin:0">Profit and loss</h2><span class="muted"><a href="/staff/reports">&larr; Reports</a> &middot; Owner only. Amounts before GST. Based on invoice and bill dates, not on when money moved.</span></div>
<form class="filters" method="get" style="margin:0"><input type="date" name="from" value="<?= e($from) ?>"><input type="date" name="to" value="<?= e($to) ?>"><button class="btn alt sm">Apply</button></form></div>
<div class="kpi"><div class="card"><span class="muted">Sales less credit notes</span><b><?= e(money($sales - $credits)) ?></b></div><div class="card"><span class="muted">Purchases (supplier bills)</span><b><?= e(money($bills)) ?></b></div><div class="card"><span class="muted">Expenses</span><b><?= e(money($expTotal)) ?></b></div><div class="card"><span class="muted">Profit</span><b class="<?= $net < 0 ? 'overdue' : '' ?>"><?= e(money($net)) ?></b></div></div>
<div class="grid g2" style="align-items:start"><div class="card"><h3>Statement</h3><dl class="kv"><dt>Sales (invoiced)</dt><dd><?= e(money($sales)) ?></dd><dt>Credit notes</dt><dd>- <?= e(money($credits)) ?></dd><dt>Purchases</dt><dd>- <?= e(money($bills)) ?></dd><dt>Expenses</dt><dd>- <?= e(money($expTotal)) ?></dd><dt><b>Profit</b></dt><dd><b><?= e(money($net)) ?></b></dd></dl>
<h3 class="mt">Cash view</h3><dl class="kv"><dt>Money received</dt><dd><?= e(money($cashIn)) ?></dd><dt>Money paid out</dt><dd><?= e(money($cashOut)) ?></dd><dt>Net cash</dt><dd><?= e(money($cashIn - $cashOut)) ?></dd></dl></div>
<div><div class="card mb"><h3>Expenses by category</h3><dl class="kv"><?php foreach ($exp as $e): ?><dt><?= e($e['category']) ?></dt><dd><?= e(money($e['a'])) ?></dd><?php endforeach; if (!$exp): ?><dt class="muted">None</dt><dd></dd><?php endif; ?></dl></div>
<div class="card"><h3>By month</h3><div class="tw"><table><tr><th>Month</th><th class="right">Income</th><th class="right">Costs</th><th class="right">Profit</th></tr><?php foreach ($months as $m): ?><tr><td><?= e(date('M Y', strtotime($m['m'] . '-01'))) ?></td><td class="right"><?= e(money($m['inc'])) ?></td><td class="right"><?= e(money($m['cost'])) ?></td><td class="right"><?= e(money($m['inc'] - $m['cost'])) ?></td></tr><?php endforeach; if (!$months): ?><tr><td colspan="4" class="muted">No data.</td></tr><?php endif; ?></table></div></div></div></div>
